coverage=[]
for name in names:
 text=(p/'proposed/content/chapters'/name).read_text(encoding='utf-8')
 section=None;mathblock=False;units=[]
 for m in re.finditer(r'\S[\s\S]*?(?=\n\s*\n|\Z)',text):
  part=m.group(0).strip()
  if part.startswith('#'):
   ids=re.findall(r'\{#([^}]+)\}',part)
   if ids:section=ids[-1]
  if part.startswith(('$$','{{block:','<div','</div',':::','#')):
   continue
  if not part:continue
  line=text[:m.start()].count('\n')+1
  matching=[r['id'] for r in repairs if r['file']==name and r['old'] in part]
  units.append({'line':line,'section':section,'paragraph_sha256':hashlib.sha256(part.encode()).hexdigest(),'passage':part,'decision':'revise' if matching else 'retain','repair_ids':matching,'section_assessment':section})
 coverage.append({'file':name,'source_sha256':sha(p/'proposed/content/chapters'/name),'paragraphs':units})
for r in repairs:
 assert r['old'] in (p/'proposed/content/chapters'/r['file']).read_text(encoding='utf-8'),r['id']
