 c['decision']='revise' if any(x['section']==r['section'] and x['file']==r['file'] and (x['id']=='S2-IE-02' and 'Translation invariance' in r['passage'] or x['id']=='S2-IE-01' and 'Attaining equality' in r['passage']) for x in repairs) else 'retain'
 c['necessity_and_terminology_answer']=notes.get(r['section'],'Retain the existing definition and its mathematical use; the function names identify the objects in the equations.')
